'use strict';

const { json } = require('../http');

/**
 * Error with an HTTP status and the API error body:
 * { "error": { "code", "message", "details": [ { field, message } ] } }
 */
class ApiError extends Error {
    constructor(status, code, message, details = []) {
        super(message);
        this.name = 'ApiError';
        this.status = status;
        this.code = code;
        this.details = Array.isArray(details) ? details : [];
    }
}

function errorResponse(err) {
    return json(err.status, { error: { code: err.code, message: err.message, details: err.details } });
}

function validationFailed(details = [], message = 'Some fields are invalid') {
    return new ApiError(400, 'VALIDATION_FAILED', message, details);
}

function referenceNotFound(details = [], message = 'A referenced record does not exist') {
    return new ApiError(400, 'REFERENCE_NOT_FOUND', message, details);
}

function notFound(message = 'Not found') {
    return new ApiError(404, 'NOT_FOUND', message);
}

function unauthorized(message = 'Please sign in again') {
    return new ApiError(401, 'UNAUTHORIZED', message);
}

function conflict(code, message, details = []) {
    return new ApiError(409, code, message, details);
}

function internalError() {
    return new ApiError(500, 'INTERNAL_ERROR', 'Something went wrong');
}

module.exports = {
    ApiError,
    errorResponse,
    validationFailed,
    referenceNotFound,
    notFound,
    unauthorized,
    conflict,
    internalError,
};
